// S3 API conformance: the engine primitive as seen by the host.
//
// Pure Dart (no Flutter imports) so the same suite runs inside the desktop app,
// in unit tests with a fake executor and headless from tool/s3_conformance.dart.
// Wire contract: contracts/transport_contract.md, "S3 API conformance".

/// Body sent with PutObject, UploadPart or a presigned PUT.
class S3OpBody {
  const S3OpBody._(this._json, this.length);

  /// Deterministic generated bytes; see [ConformanceBytes.generate].
  factory S3OpBody.generate(int size, int seed) =>
      S3OpBody._({'generate': {'size': size, 'seed': seed}}, size);

  factory S3OpBody.text(String text) =>
      S3OpBody._({'text': text}, _utf8Length(text));

  factory S3OpBody.base64(String encoded, int length) =>
      S3OpBody._({'base64': encoded}, length);

  final Map<String, Object?> _json;
  final int length;

  Map<String, Object?> toJson() => _json;

  static int _utf8Length(String text) {
    var length = 0;
    for (final rune in text.runes) {
      length += rune < 0x80
          ? 1
          : rune < 0x800
              ? 2
              : rune < 0x10000
                  ? 3
                  : 4;
    }
    return length;
  }
}

/// One `s3ConformanceOp` request.
class S3OpRequest {
  const S3OpRequest(
    this.op,
    this.input, {
    this.body,
    this.customerKey,
    this.sourceCustomerKey,
  });

  final String op;
  final Map<String, Object?> input;
  final S3OpBody? body;

  /// Base64 SSE-C key for the addressed object. A secret: never logged,
  /// reported or exported.
  final String? customerKey;

  /// Base64 SSE-C key for the copy source. A secret.
  final String? sourceCustomerKey;

  Map<String, Object?> toParams() => {
        'op': op,
        'input': input,
        if (body != null) 'body': body!.toJson(),
        if (customerKey != null)
          'encryption': {'mode': 'sse-c', 'customerKey': customerKey},
        if (sourceCustomerKey != null)
          'sourceEncryption': {
            'mode': 'sse-c',
            'customerKey': sourceCustomerKey
          },
      };
}

/// What an engine observed for one operation.
class S3OpObservation {
  const S3OpObservation({
    required this.op,
    required this.outcome,
    required this.httpStatus,
    this.errorCode,
    this.errorMessage,
    this.headers = const {},
    this.output = const {},
    this.latencyMs = 0,
    this.attempts = 1,
    this.requestId,
  });

  factory S3OpObservation.fromJson(Map<String, Object?> json) {
    final headers = <String, String>{};
    final rawHeaders = json['headers'];
    if (rawHeaders is Map) {
      for (final entry in rawHeaders.entries) {
        headers[entry.key.toString().toLowerCase()] = '${entry.value}';
      }
    }
    final output = json['output'];
    return S3OpObservation(
      op: '${json['op'] ?? ''}',
      outcome: '${json['outcome'] ?? 'service'}',
      httpStatus: (json['httpStatus'] as num?)?.toInt() ?? 0,
      errorCode: json['errorCode']?.toString(),
      errorMessage: json['errorMessage']?.toString(),
      headers: headers,
      output: output is Map ? Map<String, Object?>.from(output) : const {},
      latencyMs: (json['latencyMs'] as num?)?.toDouble() ?? 0,
      attempts: (json['attempts'] as num?)?.toInt() ?? 1,
      requestId: json['requestId']?.toString(),
    );
  }

  final String op;

  /// `service`, `sdk_validation`, `sdk_decode` or `transport`.
  final String outcome;
  final int httpStatus;
  final String? errorCode;
  final String? errorMessage;
  final Map<String, String> headers;
  final Map<String, Object?> output;
  final double latencyMs;
  final int attempts;
  final String? requestId;

  bool get isService => outcome == 'service';
  /// A 2xx without an embedded S3 error.
  bool get isSuccess => isService && httpStatus >= 200 && httpStatus < 300 && errorCode == null;
  String? header(String name) => headers[name.toLowerCase()];

  /// Reads a path such as `Contents.0.Key` from [output].
  Object? field(String path) {
    Object? current = output;
    for (final part in path.split('.')) {
      if (current is Map) {
        current = current[part];
      } else if (current is List) {
        final index = int.tryParse(part);
        if (index == null || index < 0 || index >= current.length) return null;
        current = current[index];
      } else {
        return null;
      }
    }
    return current;
  }

  List<Map<String, Object?>> list(String path) {
    final value = field(path);
    if (value is! List) return const [];
    return [
      for (final item in value)
        if (item is Map) Map<String, Object?>.from(item)
    ];
  }
}

/// RPC-level failure of `s3ConformanceOp` (not a service response).
class S3OpRpcException implements Exception {
  const S3OpRpcException(this.code, this.message);

  /// `unsupported_feature`, `invalid_request`, `invalid_config`,
  /// `engine_unavailable`, `timeout`, ...
  final String code;
  final String message;

  bool get isUnsupported => code == 'unsupported_feature' || code == 'unsupportedFeature';

  @override
  String toString() => 'S3OpRpcException($code): $message';
}

/// Executes conformance operations through one desktop engine.
abstract class S3OpExecutor {
  String get engineId;

  /// Engine-reported capability (`conformance.s3`), or null when absent.
  Future<S3ConformanceCapability?> capability();

  Future<S3OpObservation> execute(S3OpRequest request);
}

class S3ConformanceCapability {
  const S3ConformanceCapability({
    required this.supported,
    required this.version,
    required this.sdk,
    required this.ops,
    this.client = const {},
    this.reason,
  });

  factory S3ConformanceCapability.fromJson(Map<String, Object?> json) =>
      S3ConformanceCapability(
        supported: '${json['state']}' == 'supported',
        version: (json['version'] as num?)?.toInt() ?? 0,
        sdk: '${json['sdk'] ?? ''}',
        ops: {
          for (final op in (json['ops'] as List?) ?? const []) '$op',
        },
        client: json['client'] is Map
            ? Map<String, Object?>.from(json['client'] as Map)
            : const {},
        reason: json['reason']?.toString(),
      );

  final bool supported;
  final int version;
  final String sdk;
  final Set<String> ops;
  final Map<String, Object?> client;
  final String? reason;

  Map<String, Object?> toJson() => {
        'supported': supported,
        'version': version,
        'sdk': sdk,
        'client': client,
        'opCount': ops.length,
        if (reason != null) 'reason': reason,
      };
}

/// Host-side backstop for engine results: removes credential values, SigV4
/// signing values and URL query strings (presigned signatures) before anything
/// is recorded, even if an engine or endpoint echoed them.
///
/// Free-form diagnostics (`errorMessage`, `errorCode`, `requestId`) lose every
/// credential whatever its length and are clipped only afterwards. S3 data
/// (`output`, `headers`) loses credentials of 16 characters or more: shorter
/// ones, such as an emulator's `test`, are ordinary words there.
Map<String, Object?> scrubConformanceResult(
    Map<String, Object?> json, Iterable<String?> secrets) {
  final all = [
    for (final secret in secrets)
      if (secret != null && secret.isNotEmpty) secret
  ]..sort((a, b) => b.length.compareTo(a.length));
  final long = [for (final secret in all) if (secret.length >= 16) secret];
  final query = RegExp(r"""(https?://[^\s?"']*)\?[^\s"']*""", caseSensitive: false);
  final signing = RegExp(
      r"""((?:x-amz-)?(?:signature|credential|security-token|securitytoken)\s*[=:]\s*)[^\s&,;"'<]+|(authorization\s*[=:]\s*)[^\n"'<]+""",
      caseSensitive: false);
  String text(String value, List<String> values, {bool diagnostic = false}) {
    var out = value.replaceAllMapped(query, (m) => '${m[1]}?[query]');
    if (diagnostic) {
      out = out.replaceAllMapped(signing, (m) => '${m[1] ?? m[2]}[redacted]');
    }
    for (final secret in values) {
      out = out.replaceAll(secret, '[redacted]');
    }
    return out;
  }

  Object? visit(Object? value) {
    if (value is String) return text(value, long);
    if (value is List) return [for (final item in value) visit(item)];
    if (value is Map) {
      return {for (final entry in value.entries) '${entry.key}': visit(entry.value)};
    }
    return value;
  }

  final headers = json['headers'];
  return {
    for (final entry in json.entries)
      entry.key: switch (entry.key) {
        'errorMessage' || 'errorCode' || 'requestId' when entry.value is String =>
          () {
            final scrubbed = text(entry.value as String, all, diagnostic: true);
            return scrubbed.length <= 256 ? scrubbed : scrubbed.substring(0, 256);
          }(),
        'headers' when headers is Map => {
            for (final header in headers.entries)
              '${header.key}': _urlHeader('${header.key}')
                  ? visit('${header.value}'.replaceFirst(RegExp(r'\?.*$'), '?[query]'))
                  : visit(header.value)
          },
        _ => visit(entry.value),
      },
  };
}

bool _urlHeader(String name) {
  final lower = name.toLowerCase();
  return lower == 'location' || lower == 'x-amz-website-redirect-location';
}
